parameters.query:
select id, name, vchasno_account
from clients
where active = true and vchasno_account is not null;

parameters.jsCode:
// Розгортаємо відповідь у по-документні items і одразу рахуємо ключі ідемпотентності.
const out = [];
for (const item of $input.all()) {
  const client = item.json.id || item.json.client_id;
  const docs = item.json.documents || item.json.data || [];
  for (const d of docs) {
    const number = String(d.number ?? d.doc_number ?? '').trim();
    const date = String(d.date ?? d.doc_date ?? '').slice(0, 10);
    const edrpou = String(d.counterparty?.edrpou ?? d.sender_edrpou ?? '').trim();
    const type = String(d.type ?? 'ВН').trim();
    if (!number || !date) continue; // без номера й дати природного ключа немає — у DLQ
    out.push({
      json: {
        client_id: client,
        source: 'vchasno',
        source_ref: String(d.id),
        natural_key: [client, edrpou, type, number, date].join('|'),
        doc_type: type,
        doc_number: number,
        doc_date: date,
        cp_edrpou: edrpou,
        cp_name: d.counterparty?.name ?? d.sender_name ?? '',
        signed: Boolean(d.signed ?? true),
        raw: d
      }
    });
  }
}
return out;

// XML українського ЕДО вже містить усі поля — модель не викликаємо.
// confidence = 'n/a': нема чого оцінювати, дані не розпізнані, а прочитані.
const src = $('Розгорнути й порахувати ключі').all();
const out = [];
$input.all().forEach((item, i) => {
  const meta = src[i] ? src[i].json : {};
  const x = item.json.parsed ?? item.json;
  const lines = (x.lines ?? x.rows ?? []).map((l, n) => ({
    line_no: n + 1,
    raw_name: String(l.name ?? '').trim(),
    raw_unit: l.unit ?? null,
    qty: Number(l.qty ?? 0),
    price: Number(l.price ?? 0),
    amount: Number(l.amount ?? 0),
    vat_amount: Number(l.vat ?? 0),
    nomenclature_code: l.code ?? null
  }));
  out.push({ json: {
    ...meta,
    confidence: 'n/a',
    amount_base: Number(x.total_without_vat ?? 0),
    amount_vat: Number(x.total_vat ?? 0),
    amount_total: Number(x.total ?? 0),
    lines,
    extracted: { channel: 'vchasno-xml', received_at: new Date().toISOString() }
  }});
});
return out;
